shellCss:
& {

  --butter: #F6E7A1;
  --butter-deep: #EBD77A;
  --butter-pale: #FBF3CF;

  --white: #FFFFFF;

  --indigo: #2B2F8F;
  --indigo-deep: #1B1E5C;
  --ink: #14163A;
  --muted: #4F5280;

  --up: #1F7A4D;
  --down: #B3261E;
  --unchanged: #4F5280;
  --behind: #8A5A00;

  --hairline: rgba(20, 22, 58, 0.14);
  --hairline-soft: rgba(20, 22, 58, 0.08);

  --font-display: "Big Shoulders Display", "Arial Narrow", sans-serif;
  --font-ui: "Manrope", "Helvetica Neue", Arial, sans-serif;

  --ease-shuttle: cubic-bezier(0.36, 0.01, 0.10, 1);
  --ease-knot: cubic-bezier(0.22, 1.12, 0.36, 1);
  --dur-fast: 0.11s;
  --dur-base: 0.38s;
  --dur-slow: 1.2s;

  --module-gap: 24px;
  --card-radius: 16px;
  --bar-h: 56px;
  --pad: 24px;
}



* { box-sizing: border-box; margin: 0; padding: 0; }
& {
  font-family: var(--font-ui);
  font-size: 16px;
  line-height: 1.4;
  color: var(--ink);
  background: var(--white);
  font-feature-settings: "tnum" 1;
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
}
a { color: var(--indigo); text-decoration: none; }
button, input { font: inherit; color: inherit; }
svg { display: block; }

.app {
  width: 100%;
  height: 100%;
  display: grid;
  grid-template-rows: var(--bar-h) minmax(0, 1fr) auto;
  background: var(--white);
}


.bar {
  height: var(--bar-h);
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 0 var(--pad);
  border-bottom: 1px solid var(--hairline);
  background: var(--white);
}
.lockup {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--indigo);
  height: 24px;
}
.lockup .mark { width: 24px; height: 24px; color: var(--indigo); }
.lockup .wordmark {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 30px;         
  line-height: 24px;
  letter-spacing: 0;
  color: var(--indigo);
  transform: translateY(1px);
}
.tabs { display: flex; align-items: stretch; gap: 4px; height: var(--bar-h); }
.tab {
  position: relative;
  display: flex; align-items: center;
  padding: 0 12px;
  font-weight: 600; font-size: 14px;
  color: var(--muted);
  border: 0; background: none; cursor: pointer;
}
.tab[aria-current="page"] { color: var(--indigo); }
.tab[aria-current="page"]::after {
  content: ""; position: absolute; left: 12px; right: 12px; bottom: 0;
  height: 2px; background: var(--indigo);
}
.bar .right { margin-left: auto; display: flex; align-items: center; gap: 16px; }
.datepill {
  display: inline-flex; align-items: center; height: 32px; padding: 0 12px;
  border: 1px solid var(--hairline); border-radius: 999px;
  font-size: 13px; font-weight: 600; color: var(--ink);
}
.bell {
  display: inline-flex; align-items: center; gap: 6px;
  height: 32px; padding: 0 10px 0 8px;
  border: 1px solid var(--hairline); border-radius: 999px;
  font-size: 13px; font-weight: 600; color: var(--indigo);
  background: none;
}
.bell svg { width: 18px; height: 18px; }
.avatar {
  width: 32px; height: 32px; border-radius: 50%;
  background: var(--indigo); color: var(--butter);
  display: inline-flex; align-items: center; justify-content: center;
  font-family: var(--font-display); font-weight: 700; font-size: 16px; letter-spacing: 0;
}


.content {
  padding: var(--pad);
  overflow: hidden;
  display: grid;
  grid-template-columns: minmax(0, 62fr) minmax(0, 38fr);
  column-gap: var(--module-gap);
  align-content: start;
}
.content.one { grid-template-columns: minmax(0, 1fr); }
.main, .rail { display: flex; flex-direction: column; gap: var(--module-gap); min-width: 0; }

.eyebrow { font-size: 13px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0; }
h1, .h1 {
  font-family: var(--font-display); font-weight: 800; font-size: 34px; line-height: 1.05;
  color: var(--indigo); letter-spacing: 0;
}
.subline { font-size: 14px; color: var(--muted); margin-top: 6px; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.subline .sep { color: var(--butter-deep); }
.status {
  display: inline-flex; align-items: center; height: 24px; padding: 0 10px;
  border-radius: 999px; background: var(--butter-pale); border: 1px solid var(--butter-deep);
  font-size: 12px; font-weight: 600; color: var(--indigo-deep);
}
.status.ok { background: var(--white); border-color: var(--hairline); color: var(--up); }
.status.behind { background: var(--white); border-color: var(--hairline); color: var(--behind); }
.head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.head .actions { display: flex; align-items: center; gap: 12px; padding-top: 4px; flex: 0 0 auto; }

.btn {
  display: inline-flex; align-items: center; justify-content: center;
  height: 40px; padding: 0 18px; border-radius: 999px; border: 0; cursor: pointer;
  font-weight: 700; font-size: 14px; background: var(--indigo); color: var(--butter); white-space: nowrap;
}
.btn:active { background: var(--indigo-deep); }
.chip {
  display: inline-flex; align-items: center; height: 30px; padding: 0 12px;
  border-radius: 999px; border: 1px solid var(--indigo); color: var(--indigo);
  font-size: 13px; font-weight: 600; background: var(--white); white-space: nowrap; cursor: pointer;
}
.chip.on { background: var(--indigo); color: var(--butter); }
.link { font-size: 14px; font-weight: 600; color: var(--indigo); }
.stamp { font-size: 13px; color: var(--muted); }
.fig { font-weight: 700; font-feature-settings: "tnum" 1; }
.fig.em { text-decoration: underline; text-decoration-color: var(--indigo); text-decoration-thickness: 2px; text-underline-offset: 3px; }


.card {
  background: var(--white); border: 1px solid var(--hairline); border-radius: var(--card-radius);
  padding: 20px;
}
.card h2 { font-family: var(--font-display); font-weight: 700; font-size: 20px; line-height: 1.1; color: var(--indigo); letter-spacing: 0; }
.card .rows { display: flex; flex-direction: column; }
.card .row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 0; border-top: 1px solid var(--hairline-soft); font-size: 14px; }
.card .row:first-child { border-top: 0; }
.card .foot { font-size: 12px; color: var(--muted); margin-top: 12px; line-height: 1.45; }


.thread {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: var(--font-display); font-weight: 600; font-size: 15px; line-height: 1;
  color: var(--indigo-deep); letter-spacing: 0; white-space: nowrap;
}
.thread svg { width: 18px; height: 18px; color: var(--indigo); }


.tiles { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.tile { border: 1px solid var(--hairline); border-radius: var(--card-radius); padding: 12px 16px; min-width: 0; }
.tile .label { font-size: 13px; font-weight: 600; color: var(--muted); }
.tile .value { font-size: 24px; font-weight: 700; color: var(--ink); line-height: 1.15; margin-top: 3px; }
.tile .note { font-size: 12px; color: var(--muted); margin-top: 2px; display: flex; align-items: center; gap: 4px; }


.up { color: var(--up); font-weight: 700; display: inline-flex; align-items: center; gap: 2px; }
.down { color: var(--down); font-weight: 700; display: inline-flex; align-items: center; gap: 2px; }
.flat { color: var(--unchanged); font-weight: 600; }
.up svg, .down svg { width: 12px; height: 12px; }


.toggle {
  position: relative; width: 44px; height: 24px; border-radius: 999px; flex: 0 0 auto;
  border: 0; cursor: pointer; background: var(--butter-deep);
  transition: background var(--dur-base) var(--ease-knot);
}
.toggle::before {
  content: ""; position: absolute; top: 3px; left: 3px; width: 18px; height: 18px; border-radius: 50%;
  background: var(--white); transition: transform var(--dur-base) var(--ease-knot);
}
.toggle[aria-checked="true"] { background: var(--indigo); }
.toggle[aria-checked="true"]::before { transform: translateX(20px); }


.bar-track { position: relative; height: 10px; border-radius: 999px; background: var(--butter-pale); overflow: visible; }
.bar-fill { height: 100%; border-radius: 999px; background: var(--indigo); transition: width var(--dur-base) var(--ease-shuttle); }
.bar-track .tick { position: absolute; top: -3px; width: 1px; height: 16px; background: var(--hairline); }


.app-footer {
  padding: 10px var(--pad) 12px;
  border-top: 1px solid var(--hairline);
  font-size: 12px; color: var(--muted);
  background: var(--white);
}


.tabs.phone { display: none; }
&.is-phone {
  & { --bar-h: 48px; --pad: 16px; --module-gap: 20px; }
& { overflow: hidden; }
  .app { grid-template-rows: var(--bar-h) 44px minmax(0, 1fr) auto; }
  .bar { gap: 12px; }
  .lockup { height: 20px; gap: 6px; }
  .lockup .mark { width: 20px; height: 20px; }
  .lockup .wordmark { font-size: 25px; line-height: 20px; }
  .bar .tabs { display: none; }
  .tabs.phone {
    display: flex; height: 44px; overflow-x: auto; scrollbar-width: none;
    padding: 0 var(--pad); gap: 4px; border-bottom: 1px solid var(--hairline);
  }
  .tabs.phone::-webkit-scrollbar { display: none; }
  .tabs.phone .tab { height: 44px; white-space: nowrap; }
  .tabs.phone .tab[aria-current="page"]::after { bottom: 0; }
  .bar .right { gap: 8px; }
  .datepill { display: none; }
  .bell { padding: 0 8px; }
  .content { grid-template-columns: minmax(0, 1fr); row-gap: var(--module-gap); overflow: hidden; }
  .content .rail { order: 2; }
  h1, .h1 { font-size: 30px; }
  .tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .tile { padding: 12px 14px; }
  .tile .value { font-size: 22px; }
  .head { gap: 12px; }
  .head .actions { padding-top: 2px; }
  .btn { height: 36px; padding: 0 14px; font-size: 13px; }
  .app-footer { font-size: 11px; padding: 8px var(--pad) 10px; }
}

today.css:
.brief-head .subline { margin-top: 8px; }
  .items { display: flex; flex-direction: column; border-top: 1px solid var(--hairline); }
  .item {
    display: grid; grid-template-columns: 92px minmax(0, 1fr) auto; column-gap: 14px; align-items: start;
    padding: 11px 0; border-bottom: 1px solid var(--hairline);
  }
  .item .thread { padding-top: 3px; }
  .item h3 { font-size: 16.5px; font-weight: 700; line-height: 1.3; color: var(--ink); }
  .item p { font-size: 16px; line-height: 1.35; color: var(--muted); margin-top: 2px; }
  .item .chip { margin-top: 2px; }
  .linkrow { display: flex; gap: 24px; }
  .goal .amount { display: flex; align-items: baseline; gap: 6px; margin-top: 8px; }
  .goal .amount .fig { font-size: 24px; }
  .goal .amount .of { font-size: 14px; color: var(--muted); }
  .goal .bar-track { margin: 12px 0 10px; }
  .goal .line { display: flex; justify-content: space-between; align-items: center; font-size: 14px; }
  .texts .row span { flex: 1; }
  .week .row { justify-content: space-between; }
  &.is-phone {
    .item { grid-template-columns: minmax(0, 1fr); row-gap: 6px; }
    .item h3 { font-size: 16px; }
    .item p { font-size: 15px; }
    .item .chip { justify-self: start; }
  }

rates.css:
.content { grid-template-columns: minmax(0, 70fr) minmax(0, 30fr); }
  .content > .head, .content > .controls { grid-column: 1 / -1; }
  .content { row-gap: var(--module-gap); }
  .controls { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
  .controls .chips { display: flex; gap: 8px; }
  .field {
    display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 12px;
    border: 1px solid var(--hairline); border-radius: 10px; font-size: 14px; color: var(--ink);
  }
  .field .label { color: var(--muted); font-weight: 600; font-size: 13px; }
  .field .fig { font-size: 15px; }
  .field svg { width: 12px; height: 12px; color: var(--muted); }
  .controls .sort { margin-left: auto; }
  .pill { display: inline-flex; align-items: center; height: 28px; padding: 0 10px; border-radius: 999px; border: 1px solid var(--hairline); font-size: 13px; font-weight: 600; color: var(--muted); }

  table { width: 100%; border-collapse: collapse; font-size: 14px; }
  thead th { text-align: left; font-size: 12px; font-weight: 600; color: var(--muted); padding: 0 10px 10px; border-bottom: 1px solid var(--hairline); white-space: nowrap; }
  thead th.num, td.num { text-align: right; }
  tbody td { padding: 9px 10px; border-bottom: 1px solid var(--hairline-soft); vertical-align: middle; white-space: nowrap; }
  tbody tr:last-child td { border-bottom: 1px solid var(--hairline); }
  tbody tr.selected td { background: var(--butter-pale); }
  tbody tr.selected td:first-child { border-radius: 10px 0 0 10px; }
  tbody tr.selected td:last-child { border-radius: 0 10px 10px 0; }
  td.mono-cell { width: 32px; padding-right: 0; }
  .mono { width: 32px; height: 32px; border-radius: 8px; background: var(--butter-pale); border: 1px solid var(--butter-deep); color: var(--indigo-deep); display: inline-flex; align-items: center; justify-content: center; font-family: var(--font-display); font-weight: 700; font-size: 15px; }
  .inst .name { font-weight: 700; color: var(--ink); }
  .inst .name small { font-weight: 500; color: var(--muted); font-size: 12px; }
  td.apy { font-size: 20px; font-weight: 700; color: var(--ink); }
  .toggle.sm { width: 36px; height: 20px; }
  .toggle.sm::before { width: 14px; height: 14px; }
  .toggle.sm[aria-checked="true"]::before { transform: translateX(16px); }
  .tag { display: inline-flex; align-items: center; height: 24px; padding: 0 8px; border-radius: 999px; background: var(--indigo); color: var(--butter); font-size: 12px; font-weight: 700; }
  .more { display: flex; justify-content: space-between; align-items: center; margin-top: 12px; }

  .detail h2 { font-size: 22px; }
  .detail .big { font-size: 32px; font-weight: 700; margin-top: 6px; line-height: 1.1; }
  .detail .big small { font-size: 14px; font-weight: 600; color: var(--muted); margin-left: 4px; }
  .chart { margin-top: 14px; }
  .chart svg { width: 100%; height: auto; }
  .detail h3 { font-size: 13px; font-weight: 600; color: var(--muted); margin-top: 16px; }
  .detail .rows .row { padding: 8px 0; }
  .detail .field { width: 100%; justify-content: space-between; margin-top: 8px; height: 40px; }

  &.is-phone {
    .content { grid-template-columns: minmax(0, 1fr); }
    .content > .head, .content > .controls { grid-column: auto; }
    .controls .sort { margin-left: 0; }
    .controls .chips { overflow-x: auto; scrollbar-width: none; max-width: 100%; }
    table, thead, tbody, tr, td { display: block; }
    thead { display: none; }
    tbody tr { display: grid; grid-template-columns: 32px auto minmax(0, 1fr); column-gap: 10px; row-gap: 2px; align-items: center; padding: 10px 0; border-bottom: 1px solid var(--hairline-soft); }
    tbody td { padding: 0; border: 0 !important; white-space: normal; }
    tbody tr.selected td { background: none; }
    td.mono-cell { grid-row: 1 / 3; grid-column: 1; width: auto; }
    td.inst-cell { grid-row: 1; grid-column: 2; white-space: nowrap; }
    td.product { grid-row: 1; grid-column: 3; font-size: 13px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    td.apy { grid-row: 2; grid-column: 2; text-align: left; font-size: 18px; }
    td.change { grid-row: 2; grid-column: 3; text-align: left; font-size: 13px; }
    td.min, td.earn, td.alert { display: none; }
    .detail { order: 3; }
  }

goals.css:
.content { row-gap: var(--module-gap); }
  .content > .head { grid-column: 1 / -1; }
  .goal-title { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }
  .amount { display: flex; align-items: baseline; gap: 8px; margin-top: 8px; }
  .amount .fig { font-size: 34px; line-height: 1.1; }
  .amount .of { font-size: 15px; color: var(--muted); }
  .pct { margin-left: auto; font-size: 14px; font-weight: 700; color: var(--indigo); }
  .bar-track { margin: 14px 0 6px; }
  .bar-track.wide { height: 14px; }
  .stats { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin-top: 16px; }
  .stat { border: 1px solid var(--hairline); border-radius: 12px; padding: 10px 12px; }
  .stat .label { font-size: 12px; font-weight: 600; color: var(--muted); }
  .stat .val { font-size: 15px; font-weight: 700; margin-top: 2px; display: flex; align-items: center; }
  .deposits { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 16px; align-items: end; margin-top: 18px; }
  .deposits .bars { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 8px; align-items: end; height: 76px; }
  .deposits .b { display: flex; flex-direction: column; align-items: center; gap: 4px; }
  .deposits .b i { display: block; width: 100%; max-width: 46px; height: 44px; border-radius: 4px 4px 0 0; background: var(--indigo); }
  .deposits .b span { font-size: 11px; font-weight: 600; color: var(--muted); }
  .deposits .cap { font-size: 13px; font-weight: 700; color: var(--indigo-deep); padding-bottom: 18px; }
  .footnote { font-size: 12px; color: var(--muted); margin-top: 14px; }
  .two { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--module-gap); }
  .small .amount .fig { font-size: 26px; }
  .small .stats { grid-template-columns: repeat(2, minmax(0, 1fr)); margin-top: 12px; }
  .small .stat { padding: 8px 10px; }
  .small .line { display: flex; justify-content: space-between; align-items: center; margin-top: 12px; font-size: 13px; }
  .brief .row { flex-direction: column; align-items: flex-start; gap: 4px; padding: 10px 0; }
  .brief .row .link { font-size: 13px; }
  .brief .row .thread { margin-bottom: 2px; }
  .checkins .row span:first-child { flex: 1; }
  &.is-phone {
    .content > .head { grid-column: auto; }
    .two { grid-template-columns: minmax(0, 1fr); }
    .stats { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
    .stat { padding: 8px; }
    .stat .val { font-size: 13px; }
    .amount .fig { font-size: 30px; }
    .deposits { grid-template-columns: minmax(0, 1fr); }
    .deposits .cap { padding-bottom: 0; }
    .goal-title { flex-direction: column; align-items: flex-start; gap: 2px; }
    .goal-title .stamp { font-size: 12px; }
    .stat .label { font-size: 11px; }
  }
